#pragma once
#include <array>
#include <concepts>
#include <cstddef>
#include <string>
#include <string_view>
#include <tuple>
#include <type_traits>
#include <utility>
#include <vector>

#include "codec.hpp"
#include "error.hpp"
#include "pool.hpp"
#include "sql.hpp"

// Column-tag convention (generated by pg_tablegen):
//   Col::pg_table::name         table name
//   Col::pg_table::key          std::tuple of the primary-key column types
//   Col::pg_table::key_columns  std::array<std::string_view, N> of primary-key column names
//   Col::pg_type, Col::pg_name  column type and name
//   By::pg_table, By::key, By::key_columns   a UNIQUE locator, same shape as the table's key

namespace pg {

template <class Col>
class cell;

namespace detail {

template <class T>
inline constexpr bool is_cell = false;
template <class Col>
inline constexpr bool is_cell<pg::cell<Col>> = true;

template <class T>
inline constexpr bool is_decimal = false;
template <int S>
inline constexpr bool is_decimal<decimal<S>> = true;

// Values `+=` works on: numbers (not bool) and fixed-point decimals.
template <class T>
concept additive = (std::is_arithmetic_v<T> && !std::is_same_v<T, bool>) || is_decimal<T>;

// A... can initialize the elements of the key tuple K, in order. A cell is
// never a key component (it would hijack the copy constructor).
template <class K, class... A>
struct key_args : std::false_type {};
template <class... K, class... A>
    requires(sizeof...(K) == sizeof...(A))
struct key_args<std::tuple<K...>, A...>
    : std::bool_constant<((std::convertible_to<A, K> && !is_cell<std::remove_cvref_t<A>>) && ...)> {};

template <class K, class... A>
concept key_args_for = key_args<K, A...>::value;

// The statements of a cell; the key columns are $1..$n, the value $n+1.
struct cell_texts {
    std::string select, assign, add, sub;
    std::size_t keys;
};

// The statements of Col located by Loc's key columns, built once.
template <class Col, class Loc>
const cell_texts& texts_of() {
    static const cell_texts t = [] {
        const std::size_t n = Loc::key_columns.size();
        std::string where;
        for (std::size_t i = 0; i < n; ++i)
            where += (i ? " AND " : "") + quote_ident(Loc::key_columns[i]) + " = $" + std::to_string(i + 1);
        const std::string table = quote_ident(Col::pg_table::name), col = quote_ident(Col::pg_name);
        const std::string value = "$" + std::to_string(n + 1);
        return cell_texts{
            "SELECT " + col + " FROM " + table + " WHERE " + where,
            "UPDATE " + table + " SET " + col + " = " + value + " WHERE " + where,
            "UPDATE " + table + " SET " + col + " = " + col + " + " + value + " WHERE " + where + " RETURNING " + col,
            "UPDATE " + table + " SET " + col + " = " + col + " - " + value + " WHERE " + where + " RETURNING " + col,
            n};
    }();
    return t;
}

}  // namespace detail

// One database cell (table, row, column) used like a variable; every access is
// a round trip on the bound connection, inside its open transaction if any.
// Never inserts: a missing row throws not_found.
template <class Col>
class cell {
public:
    using value_type = typename Col::pg_type;

    // Locates the row by primary key.
    template <class... A>
        requires detail::key_args_for<typename Col::pg_table::key, A...>
    explicit cell(conn& c, A&&... key) {
        init<typename Col::pg_table>(std::index_sequence_for<A...>{}, c, std::forward<A>(key)...);
    }

    // Locates the row by a unique key.
    template <class By, class... A>
        requires detail::key_args_for<typename By::key, A...>
    cell(conn& c, By, A&&... key) {
        init<By>(std::index_sequence_for<A...>{}, c, std::forward<A>(key)...);
    }

    cell(const cell&) = default;

    // Assigning one cell to another copies the value, like variables.
    cell& operator=(const cell& other) { return *this = other.get(); }

    value_type get() const {
        const detail::reply rp = detail::run_text(
            *c_, t_->select, keys(), &detail::check_row<value_type>);
        // A unique key yields at most one row.
        if (detail::rows_in(rp) == 0) throw not_found(missing());
        return detail::decode_row<value_type>(rp, 0);
    }
    operator value_type() const { return get(); }

    cell& operator=(const value_type& v) {
        params_[t_->keys] = detail::to_param(v);
        const detail::reply rp = detail::run_text(*c_, t_->assign, all(), nullptr);
        if (detail::affected_of(rp) == 0) throw not_found(missing());
        return *this;
    }

    cell& operator+=(const value_type& d)
        requires detail::additive<value_type>
    {
        return add(false, d);
    }
    cell& operator-=(const value_type& d)
        requires detail::additive<value_type>
    {
        return add(true, d);
    }
    cell& operator++()
        requires std::is_arithmetic_v<value_type> && detail::additive<value_type>
    {
        return *this += value_type(1);
    }
    cell& operator--()
        requires std::is_arithmetic_v<value_type> && detail::additive<value_type>
    {
        return *this -= value_type(1);
    }
    cell& operator++()
        requires detail::is_decimal<value_type>
    {
        return *this += value_type::from_units(value_type::one());
    }
    cell& operator--()
        requires detail::is_decimal<value_type>
    {
        return *this -= value_type::from_units(value_type::one());
    }

private:
    template <class Loc, class... A, std::size_t... I>
    void init(std::index_sequence<I...>, conn& c, A&&... key) {
        c_ = &c;
        t_ = &detail::texts_of<Col, Loc>();
        (params_.push_back(detail::to_param(static_cast<std::tuple_element_t<I, typename Loc::key>>(key))), ...);
        params_.push_back(detail::param{});
    }

    std::span<const detail::param> keys() const { return {params_.data(), t_->keys}; }
    std::span<const detail::param> all() const { return {params_.data(), t_->keys + 1}; }

    std::string missing() const {
        return "no row for " + std::string(Col::pg_table::name) + "." + std::string(Col::pg_name);
    }

    // UPDATE … SET c = c ± $n … RETURNING c; no row is not_found.
    cell& add(bool subtract, const value_type& d) {
        params_[t_->keys] = detail::to_param(d);
        const detail::reply rp = detail::run_text(*c_, subtract ? t_->sub : t_->add, all(),
                                                  &detail::check_row<value_type>);
        if (detail::rows_in(rp) == 0) throw not_found(missing());
        return *this;
    }

    conn* c_ = nullptr;
    const detail::cell_texts* t_ = nullptr;
    detail::small_vec<detail::param, 4> params_;  // the key, then the value slot
};

}  // namespace pg
